import pandas as pd
import numpy as np
import timeit

def setup():
    np.random.seed(42)
    left = pd.DataFrame({'key': np.arange(0, 1000000, 2), 'val1': np.ones(500000, dtype=np.float64)})
    right = pd.DataFrame({'key': np.arange(500000, 700000, 1), 'val2': np.full(200000, 2, dtype=np.float64)})
    left = left.sort_values('key').reset_index(drop=True)
    right = right.sort_values('key').reset_index(drop=True)
    return (left, right)

def test1():
    # baseline
    left, right = setup()
    return pd.merge_ordered(left, right, on='key', how='inner')

def test2():
    # test with unsorted data
    np.random.seed(42)
    left = pd.DataFrame({'key': np.random.permutation(500000), 'val1': np.ones(500000, dtype=np.float64)})
    right = pd.DataFrame({'key': np.random.permutation(200000) + 500000, 'val2': np.full(200000, 2, dtype=np.float64)})
