def test3():
    # test with smaller sorted data
    left = pd.DataFrame({'key': np.arange(0, 100000, 2), 'val1': np.ones(50000, dtype=np.float64)})
    right = pd.DataFrame({'key': np.arange(50000, 70000, 1), 'val2': np.full(20000, 2, dtype=np.float64)})
